 @Override public void onStart(){Bundle out=new Bundle();try{runOnMainSync(new Runnable(){public void run(){}});Context c=getTargetContext();DurableCode.awaitReady();for(String prefs:new String[]{"banana-natural-coding","banana-app-java","banana-java-method"})c.getSharedPreferences(prefs,0).edit().clear().commit();AppJavaWorkspace.loaded=-1;AppJavaWorkspace.restore(c);Semilla model=OwnBrain.load(c);
 cmd(c,model,"quiero que cambies el color de los botones a azul","Color de botones: azul");check(AppJavaWorkspace.live.accent==1,"compiled blue buttons");cmd(c,model,"que cambiaste","Color de botones: azul");cmd(c,model,"deshace ese cambio","Recuperé la versión");check(AppJavaWorkspace.live.accent==0,"original button style recovered");
 cmd(c,model,"agranda la letra y cambia los botones a verde","Color de botones: verde");check(AppJavaWorkspace.live.text==17&&AppJavaWorkspace.live.accent==2,"two adjustments compiled and activated");int rev=AppJavaWorkspace.prefs(c).getInt("revision",0);cmd(c,model,"cambia los botones a rojo y borra mis escenas","No cambié el código ni la escena");check(AppJavaWorkspace.live.accent==2&&AppJavaWorkspace.prefs(c).getInt("revision",0)==rev,"unknown second clause has no partial side effects");
 cmd(c,model,"cuando te diga \"saludo exclusivo\" respondas \"Buenas desde mi Banana\"","La respuesta se comprobó");check("Buenas desde mi Banana".equals(JavaMethodEditor.social("saludo exclusivo")),"actual compiled reply activated");String reply=cmd(c,model,"saludo exclusivo","Buenas desde mi Banana");check(reply.equals("Buenas desde mi Banana"),"ordinary chat uses changed method");
 JavaProject.prefs(c).edit().putString("base","obsolete-test-base").commit();cmd(c,model,"crea una funcion que sume los positivos de una lista","Entendí: suma los positivos");check(JavaProject.prefs(c).contains("previousBase"),"base automatically migrated with backup");cmd(c,model,"probalo con -3,2,5","Resultado del candidato: 7");cmd(c,model,"deshace ese cambio","Recuperé la copia anterior");check(JavaProject.source(c,"JavaAlgorithm.java").contains("return input"),"method undo restores prior source");
 JSONObject portable=DurableCode.portable(c);DurableCode.validate(c,portable);check(portable.getInt("version")==3&&portable.getJSONObject("chatEdits").getJSONObject("settings").getInt("accent")==2,"normal reconstruction carries canonical settings and replies");
 out.putString("stream","PASS STAGE54 normal chat routing, actual compiled button color, batch atomic rejection, undo, executed reply and method, portable chat changes.\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
